from sqlalchemy.orm import Session
import db_models

# Example CRUD functions for RequestLog. Expand as needed.

def create_request_log(db: Session, provider: str, model: str, prompt_length: int):
    db_log = db_models.RequestLog(provider=provider, model=model, prompt_length=prompt_length)
    db.add(db_log)
    db.commit()
    db.refresh(db_log)
    return db_log

def get_request_log(db: Session, log_id: int):
    return db.query(db_models.RequestLog).filter(db_models.RequestLog.id == log_id).first()

def get_request_logs(db: Session, skip: int = 0, limit: int = 100):
    return db.query(db_models.RequestLog).order_by(db_models.RequestLog.timestamp.desc()).offset(skip).limit(limit).all()

