from typing import Dict, Any, Tuple, Optional
import httpx
import json
from .base_client import AIClient

class GeminiClient(AIClient):
    async def generate_text(self, model: str, prompt: str, params: Optional[Dict[str, Any]] = None, timeout: int = 60) -> Tuple[Optional[str], Optional[Dict[str, Any]]]:
        effective_params = params or {}
        request_url = f"{self.base_url}/{model}:generateContent?key={self.api_key}"

        payload = {
            "contents": [
                {
                    "parts": [
                        {"text": prompt}
                    ]
                }
            ],
            # Example of merging generationConfig, adjust as needed based on Gemini API
            "generationConfig": {
                "temperature": effective_params.get("temperature", 0.7),
                "maxOutputTokens": effective_params.get("maxOutputTokens", 2048),
            }
        }

        headers = self._common_headers()

        try:
            response = await self.http_client.post(request_url, json=payload, headers=headers, timeout=timeout)
            response.raise_for_status() # Will raise an HTTPError for bad responses (4XX or 5XX)

            raw_response_data = response.json()

            # Extract text - this depends heavily on Gemini's response structure
            # Assuming the response has a structure like: { "candidates": [ { "content": { "parts": [ { "text": "..." } ] } } ] }
            generated_text = None
            if raw_response_data.get("candidates") and raw_response_data["candidates"][0].get("content") and raw_response_data["candidates"][0]["content"].get("parts"):
                generated_text = raw_response_data["candidates"][0]["content"]["parts"][0].get("text")

            return generated_text, raw_response_data

        except httpx.HTTPStatusError as e:
            error_content = {}
            try:
                error_content = e.response.json()
            except json.JSONDecodeError:
                error_content = {"error": "Failed to decode error response from provider", "details": e.response.text}
            print(f"Gemini API Error ({e.response.status_code}): {error_content}")
            return None, {"error": f"Gemini API Error ({e.response.status_code})", "details": error_content}
        except httpx.RequestError as e:
            print(f"Gemini Request Error: {e}")
            return None, {"error": "Gemini Request Error", "details": str(e)}
        except Exception as e:
            print(f"Gemini Client Generic Error: {e}")
            return None, {"error": "Gemini Client Generic Error", "details": str(e)}

from typing import Dict, Any, Tuple, Optional
import httpx
import json
from .base_client import AIClient

class GroqClient(AIClient):
    # Groq uses an OpenAI-compatible API structure
    async def generate_text(self, model: str, prompt: str, params: Optional[Dict[str, Any]] = None, timeout: int = 60) -> Tuple[Optional[str], Optional[Dict[str, Any]]]:
        effective_params = params or {}
        # The base URL for Groq is typically 'https://api.groq.com/openai/v1'
        # The endpoint is '/chat/completions'
        request_url = f"{self.base_url}/chat/completions"

        payload = {
            "model": model,
            "messages": [
                {"role": "user", "content": prompt}
            ],
            "temperature": effective_params.get("temperature", 0.7),
            "max_tokens": effective_params.get("max_tokens", 1024), # Groq uses max_tokens
            # Add other OpenAI compatible params as needed from effective_params
        }
        if "stream" in effective_params:
            payload["stream"] = effective_params["stream"]

        headers = self._common_headers()
        headers["Authorization"] = f"Bearer {self.api_key}"

        try:
            response = await self.http_client.post(request_url, json=payload, headers=headers, timeout=timeout)
            response.raise_for_status()

            raw_response_data = response.json()

            # Extract text - for OpenAI-compatible non-streaming responses
            generated_text = None
            if raw_response_data.get("choices") and len(raw_response_data["choices"]) > 0:
                message = raw_response_data["choices"][0].get("message")
                if message and message.get("content"):
                    generated_text = message["content"]

            return generated_text, raw_response_data

        except httpx.HTTPStatusError as e:
            error_content = {}
            try:
                error_content = e.response.json()
            except json.JSONDecodeError:
                error_content = {"error": "Failed to decode error response from provider", "details": e.response.text}
            print(f"Groq API Error ({e.response.status_code}): {error_content}")
            return None, {"error": f"Groq API Error ({e.response.status_code})", "details": error_content}
        except httpx.RequestError as e:
            print(f"Groq Request Error: {e}")
            return None, {"error": "Groq Request Error", "details": str(e)}
        except Exception as e:
            print(f"Groq Client Generic Error: {e}")
            return None, {"error": "Groq Client Generic Error", "details": str(e)}

server {
    listen 80;
    server_name localhost;

    root /usr/share/nginx/html;
    index index.html index.htm;

    # Default location block
    location / {
        try_files $uri $uri/ /index.html;
    }

    # Optional: Caching for static assets
    location ~* \.(?:css|js|jpg|jpeg|gif|png|ico|woff|woff2|ttf|eot)$ {
        expires 1M; # Cache for 1 month
        add_header Cache-Control "public";
    }

    # Optional: Security headers
    # add_header X-Frame-Options "SAMEORIGIN" always;
    # add_header X-XSS-Protection "1; mode=block" always;
    # add_header X-Content-Type-Options "nosniff" always;
    # add_header Referrer-Policy "no-referrer-when-downgrade" always;
    # add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; font-src 'self'; connect-src 'self' http://ai_inference_gateway-backend-api:8070;" always;

    # Optional: Disable server tokens (version visibility)
