document.addEventListener('DOMContentLoaded', () => {
    // --- Constants and State ---
    const API_BASE_URL_ENV = document.body.dataset.apiBaseUrl || 'http://localhost:8070'; // Fallback if not set by .env inject
    const pageContent = document.getElementById('page-content');
    let currentTheme = localStorage.getItem('theme') || 'dark-theme';
    document.body.className = currentTheme;

    // --- API Helper ---
    async function fetchApi(endpoint, options = {}) {
        const url = `${API_BASE_URL_ENV}${endpoint}`;
        try {
            const response = await fetch(url, options);
            if (!response.ok) {
                let errorData;
                try {
                    errorData = await response.json();
                } catch (e) {
                    errorData = { message: response.statusText };
                }
                throw new Error(`HTTP error ${response.status}: ${errorData.detail || errorData.message}`);
            }
            return response.json();
        } catch (error) {
            console.error(`API Error (${url}):`, error);
            throw error;
        }
    }

    // --- UI Rendering ---
    function renderInferPage() {
        pageContent.innerHTML = `
            <div class="page infer-page">
                <div class="form-group">
                    <label for="provider-select">AI Provider:</label>
                    <select id="provider-select"></select>
                </div>
                <div class="form-group">
                    <label for="model-select">Model:</label>
                    <select id="model-select"></select>
                </div>
                <div class="form-group">
                    <label for="prompt-textarea">Prompt:</label>
                    <textarea id="prompt-textarea" placeholder="Enter your prompt here..."></textarea>
                </div>
                <button id="submit-inference" class="primary-action">Submit</button>
                <div id="response-area" class="response-area">
                    <div class="loading-indicator" style="display:none;">Processing...</div>
                    <div class="error-message" style="display:none;"></div>
                    <pre id="inference-result"></pre>
                </div>
            </div>
        `;
        loadProviders();
        document.getElementById('submit-inference').addEventListener('click', handleSubmitInference);
    }

    function renderSettingsPage() {
        pageContent.innerHTML = `
            <div class="page settings-page">
                <section class="settings-section">
                    <h2>Backend Configuration</h2>
                    <p>Current backend configuration (read-only from <code>app_config.json</code> on the server):</p>
                    <div id="backend-config-display" class="json-display loading-indicator">Loading config...</div>
                    <p>To modify API keys or provider details, edit the <code>.env</code> file and <code>service_code_backend/app_config.json</code> on the server and restart the backend service.</p>
                </section>
                 <section class="settings-section">
                    <h2>Theme Settings</h2>
                    <p>Current theme: <strong id="current-theme-display">${currentTheme.replace('-theme','')}</strong></p>
                    <button id="force-theme-toggle">Toggle Theme Manually</button>
                </section>
            </div>
        `;
        loadBackendConfig();
        document.getElementById('force-theme-toggle').addEventListener('click', toggleTheme);
    }

    // --- Inference Page Logic ---
    let availableProvidersData = [];
    async function loadProviders() {
        const providerSelect = document.getElementById('provider-select');
        const modelSelect = document.getElementById('model-select');
        if (!providerSelect || !modelSelect) return;

        try {
            availableProvidersData = await fetchApi('/api/v1/providers');
            providerSelect.innerHTML = '<option value="">Select Provider</option>';
            availableProvidersData.forEach(p => {
                const option = document.createElement('option');
                option.value = p.name;
                option.textContent = p.name;
                providerSelect.appendChild(option);
            });
            providerSelect.addEventListener('change', handleProviderChange);
        } catch (error) {
            providerSelect.innerHTML = '<option value="">Error loading providers</option>';
            console.error("Failed to load providers:", error);
        }
    }

    function handleProviderChange(event) {
        const modelSelect = document.getElementById('model-select');
        const selectedProviderName = event.target.value;
        modelSelect.innerHTML = '<option value="">Select Model</option>';
        if (selectedProviderName) {
            const provider = availableProvidersData.find(p => p.name === selectedProviderName);
            if (provider && provider.models) {
                provider.models.forEach(modelName => {
                    const option = document.createElement('option');
                    option.value = modelName;
                    option.textContent = modelName;
                    modelSelect.appendChild(option);
                });
            }
        }
    }

    async function handleSubmitInference() {
        const provider = document.getElementById('provider-select').value;
        const model = document.getElementById('model-select').value;
        const prompt = document.getElementById('prompt-textarea').value;
        const resultArea = document.getElementById('inference-result');
        const loadingIndicator = document.querySelector('.loading-indicator');
        const errorMessageElement = document.querySelector('.error-message');

        if (!provider || !model || !prompt) {
            alert('Please select a provider, model, and enter a prompt.');
            return;
        }

        resultArea.textContent = '';
        errorMessageElement.style.display = 'none';
        errorMessageElement.textContent = '';
        loadingIndicator.style.display = 'block';

        try {
            const response = await fetchApi('/api/v1/infer', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ provider, model, prompt, params: {} })
            });

            if (response.error) {
                errorMessageElement.textContent = `Error: ${response.error}`;
                if(response.details) errorMessageElement.textContent += `\nDetails: ${JSON.stringify(response.details, null, 2)}`;
                errorMessageElement.style.display = 'block';
            } else {
                resultArea.textContent = response.response_text || JSON.stringify(response.raw_response, null, 2);
            }
        } catch (error) {
            errorMessageElement.textContent = `Request failed: ${error.message}`;
            errorMessageElement.style.display = 'block';
        } finally {
            loadingIndicator.style.display = 'none';
        }
    }

    // --- Settings Page Logic ---
    async function loadBackendConfig() {
        const configDisplay = document.getElementById('backend-config-display');
        if (!configDisplay) return;

        try {
            const config = await fetchApi('/api/v1/config');
            configDisplay.textContent = JSON.stringify(config, null, 2);
            configDisplay.classList.remove('loading-indicator');
        } catch (error) {
            configDisplay.textContent = `Error loading backend configuration: ${error.message}`;
            configDisplay.classList.add('error-message');
            configDisplay.classList.remove('loading-indicator');
        }
    }

    // --- Theme Toggle ---
    const themeToggleButton = document.getElementById('theme-toggle-button');
    if (themeToggleButton) {
        themeToggleButton.addEventListener('click', toggleTheme);
    }
    function toggleTheme() {
        currentTheme = (currentTheme === 'dark-theme') ? 'light-theme' : 'dark-theme';
        document.body.className = currentTheme;
        localStorage.setItem('theme', currentTheme);
        const currentThemeDisplay = document.getElementById('current-theme-display');
        if(currentThemeDisplay) currentThemeDisplay.textContent = currentTheme.replace('-theme','');
    }

    // --- Simple Router ---
    function router() {
        const path = window.location.hash.slice(1) || '/';
        pageContent.innerHTML = ''; // Clear previous content

        if (path === '/') {
            renderInferPage();
        } else if (path === '/settings') {
            renderSettingsPage();
        } else {
            pageContent.innerHTML = '<p>Page not found.</p>';
        }
    }

    window.addEventListener('hashchange', router);
    router(); // Initial page load

    // --- Command Palette ---
    const commandPaletteModal = document.getElementById('command-palette-modal');
    const commandPaletteInput = document.getElementById('command-palette-input');
    const commandPaletteResults = document.getElementById('command-palette-results');
    let selectedCommandIndex = -1;

    const commands = [
        { name: 'Navigate: Inference Page', action: () => { window.location.hash = '#/'; closeModal(); } },
        { name: 'Navigate: Settings Page', action: () => { window.location.hash = '#/settings'; closeModal(); } },
        { name: 'Action: Toggle Theme', action: () => { toggleTheme(); closeModal(); } },
        { name: 'Action: Clear Inference Prompt', action: () => { 
            const ta = document.getElementById('prompt-textarea'); if(ta) ta.value = ''; closeModal(); 
        } },
        { name: 'Action: Clear Inference Result', action: () => { 
            const ra = document.getElementById('inference-result'); if(ra) ra.textContent = ''; closeModal(); 
        } },
    ];

    function openModal() {
        commandPaletteModal.style.display = 'flex';
        commandPaletteInput.value = '';
        renderCommands('');
        commandPaletteInput.focus();
        selectedCommandIndex = -1; 
    }

    function closeModal() {
        commandPaletteModal.style.display = 'none';
    }

    function renderCommands(filter) {
        commandPaletteResults.innerHTML = '';
        const filteredCommands = commands.filter(cmd => cmd.name.toLowerCase().includes(filter.toLowerCase()));
        filteredCommands.forEach((cmd, index) => {
            const li = document.createElement('li');
            li.textContent = cmd.name;
            li.dataset.index = index; 
            li.addEventListener('click', () => cmd.action());
            commandPaletteResults.appendChild(li);
        });
        if(filteredCommands.length > 0) {
            selectedCommandIndex = 0;
            highlightCommand(selectedCommandIndex);
        }
    }

    function highlightCommand(index) {
        const items = commandPaletteResults.querySelectorAll('li');
        items.forEach((item, i) => {
            item.classList.toggle('selected', i === index);
        });
    }

    commandPaletteInput.addEventListener('input', (e) => renderCommands(e.target.value));
    commandPaletteInput.addEventListener('keydown', (e) => {
        const items = commandPaletteResults.querySelectorAll('li');
        if (e.key === 'Escape') closeModal();
        if (e.key === 'Enter' && selectedCommandIndex !== -1 && items[selectedCommandIndex]) {
            e.preventDefault();
            const cmdIndex = parseInt(items[selectedCommandIndex].dataset.index);
            const actualCommand = commands.filter(cmd => cmd.name.toLowerCase().includes(commandPaletteInput.value.toLowerCase()))[cmdIndex];
            if(actualCommand) actualCommand.action();
        }
        if (e.key === 'ArrowDown') {
            e.preventDefault();
            if (selectedCommandIndex < items.length - 1) selectedCommandIndex++;
            highlightCommand(selectedCommandIndex);
        }
        if (e.key === 'ArrowUp') {
            e.preventDefault();
            if (selectedCommandIndex > 0) selectedCommandIndex--;
            highlightCommand(selectedCommandIndex);
        }
    });

    document.addEventListener('keydown', (e) => {
        if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
            e.preventDefault();
            if (commandPaletteModal.style.display === 'none') {
                openModal();
            } else {
                closeModal();
            }
        }
    });
    // Close modal if clicked outside
    commandPaletteModal.addEventListener('click', function(event) {
        if (event.target === commandPaletteModal) {
            closeModal();
        }
    });

    // Inject API_BASE_URL from .env if available (via a build step or server-side template)
    // For pure client-side, it must be hardcoded or configured elsewhere.
    // This example assumes it might be set on body's dataset by a wrapper or dev server.
    console.log(`Frontend initialized. API Base URL: ${API_BASE_URL_ENV}`);
});
